<?php
// 📈 बिल परवानगी पत्रक — मासिक / वार्षिक अहवाल (A4, black & white): सारांश, पत्रकनिहाय / महिनानिहाय तक्ता, पार्टीनिहाय, बिल भरणारानिहाय,
// परवानगी बाकी पत्रके, (ऐच्छिक) बिलनिहाय तपशील, सह्या व "Generated by". Excel (CSV) सुद्धा.
require_once __DIR__ . '/../../includes/auth.php';
requireLogin('../../');
require_once __DIR__ . '/../../includes/bill-sign.php';
if (!bsCanView()) { http_response_code(403); die('<div style="font-family:sans-serif;padding:40px;">बिल परवानगी पत्रक पाहण्याची परवानगी नाही.</div>'); }
$orgId = activeOrgId();
if (!bsReady($pdo)) { header('Location: index.php'); exit; }
$SET = bsSettings($pdo, $orgId);
$h = fn($x) => htmlspecialchars((string)$x, ENT_QUOTES, 'UTF-8');
$M = fn($x) => woMoney($x);
$ST = bsStatuses();

// ---------- निवड ----------
$mode = ($_GET['mode'] ?? '') === 'year' ? 'year' : 'month';
$st = $pdo->prepare("SELECT DISTINCT fy FROM bill_sign_sheets WHERE organization_id = ? ORDER BY fy DESC"); $st->execute([$orgId]); $fys = $st->fetchAll(PDO::FETCH_COLUMN);
$curFy = purchaseFy(); if (!in_array($curFy, $fys, true)) array_unshift($fys, $curFy);
$fy = preg_match('/^\d{4}-\d{2}$/', (string)($_GET['fy'] ?? '')) ? $_GET['fy'] : $curFy;
$st = $pdo->prepare("SELECT DATE_FORMAT(MAX(sheet_date), '%Y-%m') FROM bill_sign_sheets WHERE organization_id = ?"); $st->execute([$orgId]); $lastMon = $st->fetchColumn() ?: date('Y-m');
$mon = preg_match('/^\d{4}-(0[1-9]|1[0-2])$/', (string)($_GET['m'] ?? '')) ? $_GET['m'] : $lastMon;
$detail = ($_GET['detail'] ?? '') === '1';
if ($mode === 'month') { $from = $mon . '-01'; $to = date('Y-m-t', strtotime($from)); $where = "s.organization_id = ? AND s.sheet_date BETWEEN ? AND ? AND s.status <> 'draft'"; $wp = [$orgId, $from, $to]; }
else { $y = (int)substr($fy, 0, 4); $from = $y . '-04-01'; $to = ($y + 1) . '-03-31'; $where = "s.organization_id = ? AND s.fy = ? AND s.status <> 'draft'"; $wp = [$orgId, $fy]; }

// ---------- आकडे ----------
$amtSql = "SUM(CASE WHEN i.status = 'approved' THEN i.amount ELSE 0 END) ok_amt, SUM(CASE WHEN i.status = 'pending' THEN i.amount ELSE 0 END) pn_amt, SUM(CASE WHEN i.status IN ('hold', 'rejected') THEN i.amount ELSE 0 END) bad_amt,
    SUM(i.is_sub = 0 AND i.status = 'approved') ok_n, SUM(i.is_sub = 0 AND i.status = 'pending') pn_n, SUM(i.is_sub = 0 AND i.status IN ('hold', 'rejected')) bad_n";
$st = $pdo->prepare("SELECT COUNT(DISTINCT s.id) sheets, SUM(i.is_sub = 0) bills, COALESCE(SUM(i.amount), 0) amt, $amtSql,
    COALESCE(SUM(CASE WHEN s.status = 'accounts' AND i.status = 'approved' THEN i.amount ELSE 0 END), 0) ac_amt, COUNT(DISTINCT i.party) parties
    FROM bill_sign_sheets s JOIN bill_sign_items i ON i.sheet_id = s.id WHERE $where");
$st->execute($wp); $K = $st->fetch();
$st = $pdo->prepare("SELECT AVG(TIMESTAMPDIFF(HOUR, s.submitted_at, s.approved_at)) / 24 d, MAX(TIMESTAMPDIFF(HOUR, s.submitted_at, s.approved_at)) / 24 mx FROM bill_sign_sheets s WHERE $where AND s.submitted_at IS NOT NULL AND s.approved_at IS NOT NULL AND s.approved_at >= s.submitted_at");
$st->execute($wp); $days = $st->fetch();

// पत्रकनिहाय (मासिक) / महिनानिहाय (वार्षिक)
$sheets = []; $months = [];
if ($mode === 'month') {
    $st = $pdo->prepare("SELECT s.*, SUM(i.is_sub = 0) bills, COALESCE(SUM(i.amount), 0) amt, $amtSql FROM bill_sign_sheets s JOIN bill_sign_items i ON i.sheet_id = s.id WHERE $where GROUP BY s.id ORDER BY s.sheet_date, s.sheet_no");
    $st->execute($wp); $sheets = $st->fetchAll();
} else {
    $st = $pdo->prepare("SELECT DATE_FORMAT(s.sheet_date, '%Y-%m') ym, COUNT(DISTINCT s.id) sheets, SUM(i.is_sub = 0) bills, COALESCE(SUM(i.amount), 0) amt, $amtSql,
        COALESCE(SUM(CASE WHEN s.status = 'accounts' AND i.status = 'approved' THEN i.amount ELSE 0 END), 0) ac_amt
        FROM bill_sign_sheets s JOIN bill_sign_items i ON i.sheet_id = s.id WHERE $where GROUP BY ym");
    $st->execute($wp); $byYm = []; foreach ($st->fetchAll() as $r) $byYm[$r['ym']] = $r;
    $st = $pdo->prepare("SELECT DATE_FORMAT(s.sheet_date, '%Y-%m') ym, AVG(TIMESTAMPDIFF(HOUR, s.submitted_at, s.approved_at)) / 24 d FROM bill_sign_sheets s WHERE $where AND s.submitted_at IS NOT NULL AND s.approved_at >= s.submitted_at GROUP BY ym");
    $st->execute($wp); $dYm = $st->fetchAll(PDO::FETCH_KEY_PAIR);
    for ($i = 0; $i < 12; $i++) { $ym = date('Y-m', strtotime("$from +$i month")); $months[$ym] = ($byYm[$ym] ?? ['sheets' => 0, 'bills' => 0, 'amt' => 0, 'ok_amt' => 0, 'pn_amt' => 0, 'bad_amt' => 0, 'ac_amt' => 0]) + ['days' => $dYm[$ym] ?? null]; }
}
// पार्टीनिहाय — उप-ओळीला पार्टी नसेल तर त्या बिलाची पार्टी
$par = "JOIN bill_sign_items p ON p.sheet_id = i.sheet_id AND p.sr = i.sr AND p.is_sub = 0";
$st = $pdo->prepare("SELECT COALESCE(i.party, p.party, '—') pname, SUM(i.is_sub = 0) bills, COUNT(DISTINCT s.id) sheets, COALESCE(SUM(i.amount), 0) amt,
    SUM(CASE WHEN i.status = 'approved' THEN i.amount ELSE 0 END) ok_amt FROM bill_sign_sheets s JOIN bill_sign_items i ON i.sheet_id = s.id $par WHERE $where GROUP BY pname ORDER BY amt DESC");
$st->execute($wp); $parties = $st->fetchAll();
$st = $pdo->prepare("SELECT i.paid_by, COUNT(*) bills, SUM(i.amount) amt FROM bill_sign_sheets s JOIN bill_sign_items i ON i.sheet_id = s.id WHERE $where AND i.paid_by IS NOT NULL GROUP BY i.paid_by ORDER BY amt DESC LIMIT 15");
$st->execute($wp); $payers = $st->fetchAll();
$st = $pdo->prepare("SELECT COALESCE(NULLIF(p.doc_type, ''), '—') dtype, SUM(i.is_sub = 0) bills, SUM(i.amount) amt FROM bill_sign_sheets s JOIN bill_sign_items i ON i.sheet_id = s.id $par WHERE $where GROUP BY dtype ORDER BY amt DESC");
$st->execute($wp); $types = $st->fetchAll();
$st = $pdo->prepare("SELECT s.* FROM bill_sign_sheets s WHERE $where AND s.status IN ('submitted', 'partial') ORDER BY s.submitted_at");
$st->execute($wp); $pendingSheets = $st->fetchAll();
$items = [];
if ($detail) { $st = $pdo->prepare("SELECT i.*, s.sheet_no, s.sheet_date FROM bill_sign_sheets s JOIN bill_sign_items i ON i.sheet_id = s.id WHERE $where ORDER BY s.sheet_date, s.sheet_no, i.sort_order"); $st->execute($wp); $items = $st->fetchAll(); }

$title = $mode === 'month' ? 'Monthly Report — ' . date('F Y', strtotime($from)) : 'Annual Report — F.Y. ' . substr($fy, 0, 4) . '-' . (substr($fy, 0, 2) . substr($fy, 5, 2));

// ---------- Excel ----------
if (($_GET['export'] ?? '') === 'csv') {
    while (ob_get_level()) ob_end_clean();
    header('Content-Type: text/csv; charset=utf-8'); header('Content-Disposition: attachment; filename="bill-sign-' . ($mode === 'month' ? $mon : $fy) . '.csv"');
    $o = fopen('php://output', 'w'); fwrite($o, "\xEF\xBB\xBF");
    fputcsv($o, [$SET['title'] . ' — Bill Permission Sheets — ' . $title]);
    if ($mode === 'month') {
        fputcsv($o, ['Sheet No', 'Date', 'Bills', 'Amount', 'Permission Granted', 'Pending', 'Held / Rejected', 'Submitted On', 'Permission On', 'Accounts On', 'Status']);
        foreach ($sheets as $r) fputcsv($o, [bsSheetLabel($r), purchaseDate($r['sheet_date']), $r['bills'], $r['amt'], $r['ok_amt'], $r['pn_amt'], $r['bad_amt'], $r['submitted_at'] ? purchaseDate($r['submitted_at']) : '', $r['approved_at'] ? purchaseDate($r['approved_at']) : '', $r['accounts_at'] ? purchaseDate($r['accounts_at']) : '', strip_tags($ST[$r['status']][0] ?? $r['status'])]);
    } else {
        fputcsv($o, ['Month', 'Sheets', 'Bills', 'Amount', 'Permission Granted', 'Pending', 'Held / Rejected', 'Submitted to Accounts', 'Avg Days to Permission']);
        foreach ($months as $ym => $r) fputcsv($o, [date('M Y', strtotime($ym . '-01')), $r['sheets'], $r['bills'], $r['amt'], $r['ok_amt'], $r['pn_amt'], $r['bad_amt'], $r['ac_amt'], $r['days'] !== null ? round((float)$r['days'], 1) : '']);
    }
    fputcsv($o, ['TOTAL', $K['sheets'], $K['bills'], $K['amt'], $K['ok_amt'], $K['pn_amt'], $K['bad_amt']]);
    fputcsv($o, []); fputcsv($o, ['Party', 'Bills', 'Sheets', 'Amount', 'Permission Granted']);
    foreach ($parties as $p) fputcsv($o, [$p['pname'], $p['bills'], $p['sheets'], $p['amt'], $p['ok_amt']]);
    fclose($o); exit;
}

$lh = array_values(array_filter(array_map('trim', explode("\n", (string)$SET['letterhead'])), 'strlen'));
$me = currentUser();
$genBy = trim(($me['name'] ?? '') . (!empty($me['designation']) ? ' (' . $me['designation'] . ')' : ''));
$tot = (float)$K['amt'];
$pc = fn($x) => $tot > 0 ? round((float)$x * 100 / $tot, 1) : 0;
$qs = fn(array $o = []) => 'report.php?' . http_build_query(array_merge(['mode' => $mode, 'm' => $mon, 'fy' => $fy, 'detail' => $detail ? 1 : ''], $o));
$monOpts = [];
foreach ($fys as $y0) { $yy = (int)substr($y0, 0, 4); for ($i = 11; $i >= 0; $i--) { $ym = date('Y-m', strtotime("$yy-04-01 +$i month")); if ($ym <= date('Y-m')) $monOpts[$ym] = date('M Y', strtotime($ym . '-01')); } }
krsort($monOpts);
$topParties = array_slice($parties, 0, $mode === 'month' ? 15 : 20);
$restP = array_slice($parties, count($topParties));
?>
