  td.n{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums;} td.c{text-align:center;white-space:nowrap;} tr.tot td{border:1.5px solid #111;font-weight:900;background:#F2F2F2;} tr.z td{color:#999;}
  .bg{display:inline-block;height:7px;background:#555;border-radius:2px;vertical-align:middle;} .two{display:grid;grid-template-columns:1.4fr 1fr;gap:12px;}
  .note{font-size:10px;color:#333;margin-top:4px;}
  .sg{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-top:40px;} .sg div{text-align:center;font-weight:800;font-size:11px;border-top:1px solid #111;padding-top:4px;}
  .gen{margin-top:12px;padding-top:5px;border-top:1px dashed #999;display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;font-size:9.5px;color:#333;} .gen b{color:#111;}
  .empty{border:1px dashed #999;padding:30px;text-align:center;margin:20px 0;font-size:13px;}
  @media print{ body{background:#fff;} .bar{display:none !important;} .pg{margin:0;box-shadow:none;width:auto;min-height:0;padding:0;} @page{size:A4 portrait;margin:9mm 9mm;} thead{display:table-header-group;} tr,.kp,.sg{break-inside:avoid;} h3{break-after:avoid;} }
  @media screen and (max-width:820px){ .pg{width:auto;min-height:0;margin:8px;padding:12px;overflow-x:auto;} .pg > div{min-width:700px;} }
</style>
