  <div class="tt"><div class="a">BILL PERMISSION SHEETS — <?= $h(strtoupper($title)) ?></div><div class="b"><?= $h($SET['title']) ?> · <?= $h($SET['subtitle']) ?></div><div class="c">Period: <?= $h(purchaseDate($from)) ?> to <?= $h(purchaseDate($to)) ?> · Draft sheets not included</div></div>

  <?php if (!(int)$K['sheets']): ?><div class="empty">या कालावधीत सहीसाठी जमा केलेले पत्रक नाही.</div><?php else: ?>
  <div class="kp">
