    <div><span>Permission Granted</span><b>₹<?= $h($M($K['ok_amt'])) ?></b><small><?= (int)$K['ok_n'] ?> bills · <?= $pc($K['ok_amt']) ?>%</small></div>
    <div><span>Submitted to Accounts</span><b>₹<?= $h($M($K['ac_amt'])) ?></b><small><?= $pc($K['ac_amt']) ?>% of total</small></div>
    <div><span>Permission Pending</span><b>₹<?= $h($M($K['pn_amt'])) ?></b><small><?= (int)$K['pn_n'] ?> bills · <?= count($pendingSheets) ?> sheets</small></div>
    <div><span>Held / Rejected</span><b>₹<?= $h($M($K['bad_amt'])) ?></b><small><?= (int)$K['bad_n'] ?> bills</small></div>
    <div><span>Avg. Days to Permission</span><b><?= $days['d'] !== null ? $h(round((float)$days['d'], 1)) : '—' ?></b><small>max <?= $days['mx'] !== null ? $h(round((float)$days['mx'], 1)) : '—' ?> days</small></div>
    <div><span>Biggest Party</span><b style="font-size:11.5px;"><?= $h($parties[0]['pname'] ?? '—') ?></b><small>₹<?= $h($M($parties[0]['amt'] ?? 0)) ?> · <?= $pc($parties[0]['amt'] ?? 0) ?>%</small></div>
  </div>

  <?php if ($mode === 'month'): ?>
