  <?php foreach ($sheets as $r): $d = $r['submitted_at'] && $r['approved_at'] ? max(0, round((strtotime($r['approved_at']) - strtotime($r['submitted_at'])) / 86400, 1)) : null; ?>
    <tr><td class="c"><b><?= $h(bsSheetLabel($r)) ?></b></td><td class="c"><?= $h(purchaseDate($r['sheet_date'])) ?></td><td class="c"><?= (int)$r['bills'] ?></td><td class="n"><b><?= $h($M($r['amt'])) ?></b></td><td class="n"><?= $h($M($r['ok_amt'])) ?></td><td class="n"><?= (float)$r['pn_amt'] ? $h($M($r['pn_amt'])) : '—' ?></td><td class="n"><?= (float)$r['bad_amt'] ? $h($M($r['bad_amt'])) : '—' ?></td>
      <td class="c"><?= $r['submitted_at'] ? $h(purchaseDate($r['submitted_at'])) : '—' ?></td><td class="c"><?= $r['approved_at'] ? $h(purchaseDate($r['approved_at'])) : '—' ?></td><td class="c"><?= $d !== null ? $h($d) : '—' ?></td><td class="c"><?= $r['accounts_at'] ? $h(purchaseDate($r['accounts_at'])) : '—' ?></td><td class="c" style="font-size:9.5px;"><?= $h(['submitted' => 'Pending', 'partial' => 'Partly approved', 'approved' => 'Permission granted', 'accounts' => 'Sent to Accounts'][$r['status']] ?? $r['status']) ?></td></tr>
  <?php endforeach; ?>
    <tr class="tot"><td colspan="2" class="c">TOTAL</td><td class="c"><?= (int)$K['bills'] ?></td><td class="n">₹<?= $h($M($K['amt'])) ?></td><td class="n"><?= $h($M($K['ok_amt'])) ?></td><td class="n"><?= $h($M($K['pn_amt'])) ?></td><td class="n"><?= $h($M($K['bad_amt'])) ?></td><td colspan="5" style="font-size:9.5px;font-weight:700;">(<?= $h(woWords($K['amt'])) ?>)</td></tr>
  </tbody></table>
  <?php else: $mx = max(1, ...array_values(array_map(fn($x) => (float)$x['amt'], $months))); ?>
  <h3>Month-wise Summary</h3>
  <table><thead><tr><th>Month</th><th>Sheets</th><th>Bills</th><th>Amount</th><th style="width:90px;"></th><th>Permission Granted</th><th>Pending</th><th>Held / Rejected</th><th>To Accounts</th><th>Avg Days</th></tr></thead><tbody>
  <?php foreach ($months as $ym => $r): ?>
    <tr class="<?= (int)$r['sheets'] ? '' : 'z' ?>"><td><b><?= $h(date('F Y', strtotime($ym . '-01'))) ?></b></td><td class="c"><?= (int)$r['sheets'] ?: '—' ?></td><td class="c"><?= (int)$r['bills'] ?: '—' ?></td><td class="n"><b><?= (float)$r['amt'] ? $h($M($r['amt'])) : '—' ?></b></td>
      <td><span class="bg" style="width:<?= round((float)$r['amt'] * 84 / $mx) ?>px;"></span></td><td class="n"><?= (float)$r['ok_amt'] ? $h($M($r['ok_amt'])) : '—' ?></td><td class="n"><?= (float)$r['pn_amt'] ? $h($M($r['pn_amt'])) : '—' ?></td><td class="n"><?= (float)$r['bad_amt'] ? $h($M($r['bad_amt'])) : '—' ?></td><td class="n"><?= (float)$r['ac_amt'] ? $h($M($r['ac_amt'])) : '—' ?></td><td class="c"><?= $r['days'] !== null ? $h(round((float)$r['days'], 1)) : '—' ?></td></tr>
  <?php endforeach; ?>
