  <h3>Party-wise Summary<?= $restP ? ' — Top ' . count($topParties) : '' ?></h3>
  <table><thead><tr><th style="width:26px;">#</th><th>Party Name</th><th>Bills</th><th>Sheets</th><th>Amount</th><th style="width:90px;">Share</th><th>Permission Granted</th></tr></thead><tbody>
  <?php $mxp = max(1, (float)($topParties[0]['amt'] ?? 1)); foreach ($topParties as $i => $p): ?>
    <tr><td class="c"><?= $i + 1 ?></td><td><?= $h($p['pname']) ?></td><td class="c"><?= (int)$p['bills'] ?></td><td class="c"><?= (int)$p['sheets'] ?></td><td class="n"><b><?= $h($M($p['amt'])) ?></b></td><td style="white-space:nowrap;"><span class="bg" style="width:<?= round((float)$p['amt'] * 44 / $mxp) ?>px;"></span> <?= $pc($p['amt']) ?>%</td><td class="n"><?= $h($M($p['ok_amt'])) ?></td></tr>
  <?php endforeach; if ($restP): $ra = array_sum(array_map(fn($x) => (float)$x['amt'], $restP)); ?>
    <tr><td></td><td><i>Other <?= count($restP) ?> parties</i></td><td class="c"><?= array_sum(array_map(fn($x) => (int)$x['bills'], $restP)) ?></td><td></td><td class="n"><b><?= $h($M($ra)) ?></b></td><td><?= $pc($ra) ?>%</td><td class="n"><?= $h($M(array_sum(array_map(fn($x) => (float)$x['ok_amt'], $restP)))) ?></td></tr>
  <?php endif; ?></tbody></table>

  <div class="two">
    <?php if ($payers): ?><div><h3>Bill Paid By (Advance / Cash)</h3><table><thead><tr><th>Name</th><th>Bills</th><th>Amount</th></tr></thead><tbody>
      <?php foreach ($payers as $p): ?><tr><td><?= $h($p['paid_by']) ?></td><td class="c"><?= (int)$p['bills'] ?></td><td class="n"><?= $h($M($p['amt'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
    <div><h3>Document Type</h3><table><thead><tr><th>PO / Bill</th><th>Bills</th><th>Amount</th></tr></thead><tbody>
      <?php foreach ($types as $t): ?><tr><td><?= $h($t['dtype']) ?></td><td class="c"><?= (int)$t['bills'] ?></td><td class="n"><?= $h($M($t['amt'])) ?></td></tr><?php endforeach; ?></tbody></table></div>
  </div>

  <?php if ($pendingSheets): ?>
  <h3>Permission Pending — Sheets</h3>
  <table><thead><tr><th>Sheet No.</th><th>Date</th><th>Bills</th><th>Amount</th><th>Submitted On</th><th>Days Pending</th><th>Status</th></tr></thead><tbody>
    <?php foreach ($pendingSheets as $p): ?><tr><td class="c"><b><?= $h(bsSheetLabel($p)) ?></b></td><td class="c"><?= $h(purchaseDate($p['sheet_date'])) ?></td><td class="c"><?= (int)$p['n_bills'] ?></td><td class="n"><?= $h($M($p['total_amount'])) ?></td><td class="c"><?= $p['submitted_at'] ? $h(purchaseDate($p['submitted_at'])) : '—' ?></td><td class="c"><b><?= bsAgeDays($p) ?></b></td><td class="c"><?= $p['status'] === 'partial' ? 'Partly approved' : 'Pending' ?></td></tr><?php endforeach; ?>
  </tbody></table>
  <?php endif; ?>

  <?php if ($detail && $items): $IS = bsItemStatuses(); ?>
  <h3>Bill-wise Detail</h3>
  <table><thead><tr><th>Sheet</th><th>Sr.</th><th>Tippani</th><th>Party Name</th><th>Particular</th><th>Bill No</th><th>Bill Date</th><th>Amount</th><th>Permission</th></tr></thead><tbody>
    <?php $last = 0; foreach ($items as $r): $new = (int)$r['sheet_id'] !== $last; $last = (int)$r['sheet_id']; ?>
      <tr><td class="c"><?= $new ? '<b>' . $h((int)$r['sheet_no'] ?: '—') . '</b><br><small>' . $h(purchaseDate($r['sheet_date'])) . '</small>' : '' ?></td><td class="c"><?= $r['is_sub'] ? '' : (int)$r['sr'] ?></td><td class="c"><?= $h($r['tippani_no']) ?></td><td><?= $h($r['party']) ?></td><td><?= $h($r['particular']) ?></td><td class="c"><?= $h($r['bill_no']) ?></td><td class="c"><?= $h($r['bill_date']) ?></td><td class="n"><?= $r['amount'] !== null ? $h($M($r['amount'])) : '' ?></td>
        <td class="c" style="font-size:9.5px;"><?= $r['is_sub'] ? '' : ['pending' => 'Pending', 'approved' => 'Granted', 'hold' => 'Held', 'rejected' => 'Rejected'][$r['status']] ?? '' ?></td></tr>
    <?php endforeach; ?>
  </tbody></table>
  <?php endif; ?>
  <?php endif; ?>

